effect.shader:
float gmHash2(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123); }
float gmBarLevel(float id, float t, float seed){
float h = gmHash2(vec2(id, seed));
float h2 = gmHash2(vec2(id * 1.7, seed + 3.0));
float a = sin(t * (2.0 + h * 3.0) + h * 6.2831);
float b = sin(t * (1.1 + h2 * 2.3) + h2 * 6.2831 + a * 0.8);
float c = 0.5 + 0.5 * sin(t * 0.7 + id * 0.35);
float lvl = 0.5 + 0.34 * a * c + 0.26 * b;
return clamp(lvl, 0.06, 1.0);
}
void main(){
vec2 uv = acScreenNorm;
vec4 src = texture2DCv(inputImg.texture, uv);
float n = max(floor(barCount), 4.0);
float xpos = uv.x;
if (mirrorBars) {
xpos = abs(xpos * 2.0 - 1.0);
n = max(floor(n * 0.5), 4.0);
}
float bid = floor(xpos * n);
float bf = fract(xpos * n);
float gap = clamp(barGap, 0.0, 0.8);
float barM = step(gap * 0.5, bf) * step(bf, 1.0 - gap * 0.5);
float lvl = gmBarLevel(bid, acTime * vizSpeed, vizSeed);
float maxH = barHeight * 0.01;
float inBar = step(uv.y, lvl * maxH) * barM;
float hn = clamp(uv.y / max(lvl * maxH, 1e-4), 0.0, 1.0);
vec3 barCol = mix(barColA.rgb, barColB.rgb, hn);
float tipD = uv.y - lvl * maxH;
float glow = exp(-max(tipD, 0.0) * 26.0) * barGlow * barM * step(0.0, tipD);
vec3 bars = barCol * inBar * (1.0 + barGlow * 0.2) + barCol * glow * 0.45;
if (barsOverlay) {
gl_FragColor = vec4(src.rgb * src.a + bars * src.a, src.a);
} else {
vec3 bg = vec3(0.01, 0.012, 0.02);
gl_FragColor = vec4(bg + bars, src.a);
}
}
